/**
 * Static HTML for every worksheet card, extracted from module-01..09.html.
 * Used by index.html "Print All Worksheets" as a fallback when no localStorage
 * snapshot exists — so printing works even before a module has been visited.
 * Modules 10-16 have no worksheet-card elements and are omitted.
 */
var WORKSHEET_BUNDLE = {
  'module-01.html': '<div class="worksheet-card">\n    <h3>Worksheet 1 — Observations &amp; Risk Assessment</h3>\n    <p style="font-size:0.88rem;margin:0 0 1rem;color:var(--purple);">Complete all sections using your observations from the software activities and from inspecting the physical arm.</p>\n    <div class="ws-field"><label>1. From Activity 1A — How many joints did you count on the 3D model?</label><input type="text" placeholder="e.g. 6 joints"></div>\n    <div class="ws-field"><label>2. From Activity 1A — How many links (rigid segments) did you count?</label><input type="text" placeholder="e.g. 6 links"></div>\n    <div class="ws-field"><label>3. What is the Degrees of Freedom (DoF) of the arm? (DoF = number of joints)</label><input type="text" placeholder="e.g. 6 DoF"></div>\n    <div class="ws-field"><label>4. Describe where you found the Torque Enable/Disable control in the app:</label><input type="text" placeholder="e.g. Joint Control tab, in the header area above the joint cards"></div>\n    <div class="ws-field"><label>5. What colour is the LED strip when the arm has torque disabled and is safe to approach? What colour indicates it is actively moving?</label><input type="text" placeholder="Safe to approach: ___ / Moving: ___"></div>\n    <div class="ws-field"><label>6. In your own words, why is it important to disable torque before manually adjusting the arm?</label><textarea placeholder="Write 1–2 sentences..."></textarea></div>\n    <div class="ws-field"><label>7. Complete this risk assessment for operating the robot arm in your classroom:</label></div>\n    <table class="ws-table"><thead><tr><th style="width:22%">Hazard</th><th style="width:16%">Likelihood<br>(L/M/H)</th><th style="width:16%">Severity<br>(L/M/H)</th><th style="width:14%">Risk Level</th><th style="width:32%">Control measure</th></tr></thead><tbody><tr><td><input type="text" value="Pinch at joint"></td><td><input type="text" placeholder="M"></td><td><input type="text" placeholder="H"></td><td><input type="text" placeholder="Medium"></td><td><input type="text" placeholder="Keep clear, low speed..."></td></tr><tr><td><input type="text" placeholder="Your hazard 2"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder="Control measure..."></td></tr><tr><td><input type="text" placeholder="Your hazard 3"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder="Control measure..."></td></tr><tr><td><input type="text" placeholder="Your hazard 4"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder="L/M/H"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder="Control measure..."></td></tr></tbody></table>\n    <div class="ws-field"><label>8. What PPE is required when operating the robot arm in this lab? List at least three items.</label><textarea placeholder="1. Safety glasses\n2. \n3. "></textarea></div>\n    <div class="ws-field"><label>9. Extension: Compare the working envelope of our arm with one industrial robot you have researched. How do the safety requirements differ?</label><textarea style="min-height:90px;" placeholder="Research an industrial arm (e.g. KUKA KR6, Universal Robots UR5) and compare..."></textarea></div>\n  </div>',

  'module-02.html': '<div class="worksheet-card">\n    <h3>Worksheet 2 — Mechanical Structure &amp; Materials</h3>\n    <div class="ws-field"><label>1. Sketch the arm from the side (use the 3D view as reference). Label each link and joint with numbers:</label><textarea style="min-height:120px;" placeholder="Describe or sketch here. Label: Base, Link 1, Joint 1, Link 2, Joint 2, ... End Effector"></textarea></div>\n    <div class="ws-field"><label>2. Record the approximate link lengths and joint ranges from Activity 2A:</label></div>\n    <table class="ws-table"><thead><tr><th>Segment</th><th>Approx. length (mm)</th><th>Joint min (°)</th><th>Joint max (°)</th><th>Total range (°)</th></tr></thead><tbody><tr><td><input type="text" value="Link 1 (base to shoulder)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Link 2 (shoulder to elbow)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Link 3 (elbow to wrist)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Link 4 (wrist pitch)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Link 5 (wrist roll)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Link 6 (wrist to EE)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr></tbody></table>\n    <div class="ws-field"><label>3. What material are most of the structural links on your robot arm made from? How did you identify this?</label><input type="text" placeholder="Material: ...  Identified by: ..."></div>\n    <div class="ws-field"><label>4. A motor produces 0.15 Nm of torque. If the gearbox ratio is 40:1, what is the output torque (ignoring losses)?</label><input type="text" placeholder="Output torque = ___ Nm  (Show working: 0.15 × 40 = ___)"></div>\n    <div class="ws-field"><label>5. Explain why it is better to place heavy components (like motors) near the base of the arm rather than near the end effector.</label><textarea placeholder="Because..."></textarea></div>\n    <div class="ws-field"><label>6. Describe what backlash is and explain one way it could affect the accuracy of a pick-and-place task.</label><textarea placeholder="Backlash is... It affects accuracy because..."></textarea></div>\n    <div class="ws-field"><label>7. Extension: Our arm is a serial kinematic chain. Research one parallel robot design (e.g. a delta robot). Describe one advantage and one disadvantage compared to a serial arm.</label><textarea placeholder="Parallel robot: ... Advantage: ... Disadvantage: ..."></textarea></div>\n  </div>',

  'module-03.html': '<div class="worksheet-card">\n    <h3>Worksheet 3 — Electrical Systems &amp; Live Data</h3>\n    <div class="ws-field"><label>1. What IP address did you use to connect to the Raspberry Pi?</label><input type="text" placeholder="e.g. 192.168.1.42"></div>\n    <div class="ws-field"><label>2. What connection port does the Robot Arm server use? Why is a specific port number needed?</label><textarea placeholder="Port: ___  Reason: ..."></textarea></div>\n    <div class="ws-field"><label>3. Record the live joint data you read in Activity 3B:</label></div>\n    <table class="ws-table"><thead><tr><th>Joint</th><th>Current Angle (°)</th><th>Temperature (°C)</th><th>Supply Voltage (V)</th></tr></thead><tbody><tr><td><input type="text" value="Joint 1"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr><tr><td><input type="text" value="Joint 2"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr><tr><td><input type="text" value="Joint 3"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr><tr><td><input type="text" value="Joint 4"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr><tr><td><input type="text" value="Joint 5"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr><tr><td><input type="text" value="Joint 6"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr></tbody></table>\n    <div class="ws-field"><label>4. What update interval (ms) was set in the Settings tab? Convert this to a frequency in Hz.</label><input type="text" placeholder="Interval: ___ ms → Frequency: ___ Hz"></div>\n    <div class="ws-field"><label>5. Explain the difference between half-duplex and full-duplex serial communication. Why does the servo bus use half-duplex?</label><textarea placeholder="Half-duplex means... Full-duplex means... The servo bus uses half-duplex because..."></textarea></div>\n    <div class="ws-field"><label>6. Give one example of open-loop control and one example of closed-loop control from everyday life (not from the robot arm).</label><textarea placeholder="Open-loop example: ...\nClosed-loop example: ..."></textarea></div>\n    <div class="ws-field"><label>7. The arm\'s servos use PID control internally. If the arm is at 30° and you command it to move to 90°, what is the initial error value that the PID controller sees?</label><input type="text" placeholder="Error = ___ °"></div>\n    <div class="ws-field"><label>8. Extension: Draw a block diagram of the closed-loop control system for one joint of the robot arm, from command input through to mechanical output. Label all blocks and signals.</label><textarea style="min-height:100px;" placeholder="Describe or sketch your block diagram here. Include: setpoint, error, controller, amplifier, motor, encoder, feedback path..."></textarea></div>\n  </div>',

  'module-04.html': '<div class="worksheet-card">\n    <h3>Worksheet 4 — HMI Exploration &amp; Programming</h3>\n    <div class="ws-field"><label>1. Record the range of motion for each joint from Activity 4A:</label></div>\n    <table class="ws-table"><thead><tr><th>Joint</th><th>Minimum angle (°)</th><th>Maximum angle (°)</th><th>Total range (°)</th></tr></thead><tbody><tr><td><input type="text" value="Joint 1 (Base)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Joint 2 (Shoulder)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Joint 3 (Elbow)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Joint 4 (Wrist)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Joint 5 (Wrist Pitch)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr><tr><td><input type="text" value="Joint 6 (Wrist Roll)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr></tbody></table>\n    <div class="ws-field"><label>2. In the Pendant Control tab, what happened to the arm\'s movement when you reduced speed to 20%? How did it feel different from 100%?</label><textarea placeholder="At 100% speed, the arm... At 20% speed, the arm..."></textarea></div>\n    <div class="ws-field"><label>3. Describe the sequence of blocks in your Blockly program from Activity 4B (the looping version):</label><textarea placeholder="1. Move to position 0 (Home)\n2. Wait 1000 ms\n3. ..."></textarea></div>\n    <div class="ws-field"><label>4. What is the difference between sequential and event-driven programming? Give one example of each from the robot arm application.</label><textarea placeholder="Sequential: ...\nEvent-driven: ..."></textarea></div>\n    <div class="ws-field"><label>5. List three features of the Robot Arm application that you think are good HMI design, and explain why for each.</label><textarea style="min-height:100px;" placeholder="1. Feature: ... Why it\'s good: ...\n2. Feature: ... Why it\'s good: ...\n3. Feature: ... Why it\'s good: ..."></textarea></div>\n    <div class="ws-field"><label>6. List one feature you think could be improved in the application\'s HMI design. What would you change, and why?</label><textarea placeholder="Feature to improve: ...\nMy proposed change: ...\nWhy this would be better: ..."></textarea></div>\n    <div class="ws-field"><label>7. The IEC 60073 standard specifies colour meanings for industrial controls. Why does a standard like this matter for safety? What could go wrong if each manufacturer used different colour conventions?</label><textarea placeholder="Standards matter because... If each manufacturer used different colours..."></textarea></div>\n    <div class="ws-field"><label>8. Extension: Design a pick-and-place sequence that sorts objects into two locations based on a condition. Describe your logic here.</label><textarea style="min-height:110px;" placeholder="Describe your sorting sequence: what positions you would define, what the loop logic would be, and how a conditional (if/else) would work in your program..."></textarea></div>\n  </div>',

  'module-05.html': '<div class="worksheet-card">\n    <h3>Worksheet 5 — Forces &amp; Load Analysis</h3>\n    <div class="ws-field"><label>1. Record the load readings for each pose from Activity 5A:</label></div>\n    <table class="ws-table"><thead><tr><th>Pose</th><th>Joint 1 Load</th><th>Joint 2 Load</th><th>Joint 3 Load</th><th>Joint 4 Load</th><th>Joint 5 Load</th><th>Joint 6 Load</th></tr></thead><tbody><tr><td><input type="text" value="Horizontal"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr><tr><td><input type="text" value="45° elevation"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr><tr><td><input type="text" value="Vertical (up)"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr></tbody></table>\n    <div class="ws-field"><label>2. Which joint showed the highest load in the horizontal pose? Why would you expect this?</label><textarea placeholder="Joint ___ had the highest load because..."></textarea></div>\n    <div class="ws-field"><label>3. Calculate the moment at the shoulder joint (Joint 2) when the arm is horizontal.</label><textarea placeholder="M_link2 = 0.18 × 9.81 × 0.06 = ___ Nm\nM_link3 = 0.12 × 9.81 × 0.22 = ___ Nm\nM_link4 = 0.08 × 9.81 × 0.30 = ___ Nm\nTotal = ___ Nm"></textarea></div>\n    <div class="ws-field"><label>4. If a 150 g payload is added at the end effector (0.35 m from the shoulder), what extra moment does this add at the shoulder?</label><input type="text" placeholder="Extra moment = 0.150 × 9.81 × 0.35 = ___ Nm"></div>\n    <div class="ws-field"><label>5. Explain in your own words why the load on the shoulder joint decreases as the arm is raised from horizontal to vertical.</label><textarea placeholder="As the arm rises, the perpendicular distance (moment arm) from the shoulder joint to the weight vectors..."></textarea></div>\n    <div class="ws-field"><label>6. Extension: Sketch a free body diagram for the elbow joint (Joint 3) when the arm is horizontal.</label><textarea style="min-height:100px;" placeholder="Sketch and describe your FBD here..."></textarea></div>\n  </div>',

  'module-06.html': '<div class="worksheet-card">\n    <h3>Worksheet 6 — Industrial Context &amp; Automation Cell</h3>\n    <div class="ws-field"><label>1. Sketch your automation cell layout (top view). Label: robot arm base, Home position, Pick position, Place position, safety boundary.</label><textarea style="min-height:110px;" placeholder="Describe or sketch your layout..."></textarea></div>\n    <div class="ws-field"><label>2. What was the cycle time (seconds) for one Home → Pick → Place → Home sequence?</label><input type="text" placeholder="Cycle time = ___ s  →  ___ cycles/min  →  ___ cycles/hour"></div>\n    <div class="ws-field"><label>3. What level of automation does your programmed sequence represent? Justify your answer.</label><textarea placeholder="The sequence represents ___ automation because..."></textarea></div>\n    <div class="ws-field"><label>4. Compare the articulated arm and the SCARA robot for Task A (welding a curved seam) and Task B (placing chips onto flat PCBs at 60 per minute).</label><textarea placeholder="Task A: best suited to ___ because...\nTask B: best suited to ___ because..."></textarea></div>\n    <div class="ws-field"><label>5. What safety measures would you add to your cell if it were to run unattended overnight?</label><textarea placeholder="1. \n2. \n3. "></textarea></div>\n    <div class="ws-field"><label>6. Extension: Research IFR statistics for global robot installations. Which industry sector installs the most robots, and what type are they predominantly?</label><textarea placeholder="Source: ...  Sector: ...  Robot type: ...  Number installed: ..."></textarea></div>\n  </div>',

  'module-07.html': '<div class="worksheet-card">\n    <h3>Worksheet 7 — Kinematics Exploration</h3>\n    <div class="ws-field"><label>1. Record end-effector positions for different joint angle combinations:</label></div>\n    <table class="ws-table"><thead><tr><th>θ₁ (°)</th><th>θ₂ (°)</th><th>θ₃ (°)</th><th>θ₄ (°)</th><th>θ₅ (°)</th><th>θ₆ (°)</th><th>X (mm)</th><th>Y (mm)</th><th>Z (mm)</th></tr></thead><tbody><tr><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr><tr><td><input type="text" value="90"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr><tr><td><input type="text" value="0"></td><td><input type="text" value="45"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr><tr><td><input type="text" placeholder="your choice"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr><tr><td><input type="text" placeholder="max X pose"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr></tbody></table>\n    <div class="ws-field"><label>2. When you rotated Joint 1 to 90°, did Z change? Explain why or why not.</label><textarea placeholder="Z did / did not change because Joint 1 (base rotation) controls rotation about the vertical axis, so..."></textarea></div>\n    <div class="ws-field"><label>3. What would the reverse of forward kinematics be called, and why might it be more difficult?</label><textarea placeholder="The reverse is called... It is harder because..."></textarea></div>\n    <div class="ws-field"><label>4. In the 4×4 transformation matrix, what do the values in the rightmost column (tx, ty, tz) represent?</label><input type="text" placeholder="They represent..."></div>\n    <div class="ws-field"><label>5. For a simple 2-link planar arm with L₁ = 150 mm, L₂ = 100 mm, θ₁ = 30°, θ₂ = 45°, calculate X and Y. Show your working.</label><textarea placeholder="θ₁ + θ₂ = 75°\nX = 150·cos(30°) + 100·cos(75°) = ___ + ___ = ___ mm\nY = 150·sin(30°) + 100·sin(75°) = ___ + ___ = ___ mm"></textarea></div>\n    <div class="ws-field"><label>6. Extension: Using the link lengths from Module 2, calculate the theoretical maximum X reach.</label><textarea placeholder="Maximum reach = L₁ + L₂ + L₃ + L₄ = ___ + ___ + ___ + ___ = ___ mm"></textarea></div>\n  </div>',

  'module-08.html': '<div class="worksheet-card">\n    <h3>Worksheet 8 — Control &amp; Communication</h3>\n    <div class="ws-field"><label>1. Describe what you observed at 10%, 50%, and 100% speed for the 0°→60° move on Joint 2:</label><textarea placeholder="10%: ...\n50%: ...\n100%: ..."></textarea></div>\n    <div class="ws-field"><label>2. Did the joint overshoot at high speed? Explain in terms of PID control — which term reduces overshoot?</label><textarea placeholder="Overshoot at high speed occurs because... The ___ (P/I/D) term reduces overshoot by..."></textarea></div>\n    <div class="ws-field"><label>3. Explain the difference between joint interpolation and linear interpolation. Give one application where each is the better choice.</label><textarea placeholder="Joint interpolation: ... best for...\nLinear interpolation: ... best for..."></textarea></div>\n    <div class="ws-field"><label>4. Describe the full communication path for a move command: App → WebSocket → Pi → Serial bus → Servo.</label><textarea placeholder="App: click \'Move to 60°\' → generates JSON message {joint:2, angle:60, speed:50}\nWebSocket: transmits JSON over TCP to port 8080\nPi: receives JSON, parses it, formats ST3215 serial packet...\nSerial bus: ...\nServo: ..."></textarea></div>\n    <div class="ws-field"><label>5. If the D (derivative) gain is set too high, what would you expect to see in the arm\'s motion? Why?</label><input type="text" placeholder="Too high D gain would cause... because D reacts to..."></div>\n    <div class="ws-field"><label>6. Extension: If the update interval is 100 ms, what is the maximum position update frequency? Could this cause problems for high-speed moves?</label><textarea placeholder="100 ms interval = ___ Hz update rate. For a fast move this could cause... because..."></textarea></div>\n  </div>',

  'module-09.html': '<div class="worksheet-card">\n    <h3>Worksheet 9 — Software Architecture &amp; G-code</h3>\n    <div class="ws-field"><label>1. Draw a diagram of the software layers in the robot arm system. Label each layer and the communication mechanism between them.</label><textarea style="min-height:100px;" placeholder="Layers (top to bottom):\n1. Electron App (JavaScript) ← runs on PC\n2. WebSocket (JSON over TCP/8080)\n3. Server (Raspberry Pi)\n4. Serial bus (UART, 1 Mbaud)\n5. ST3215 Servos"></textarea></div>\n    <div class="ws-field"><label>2. Write a G-code program that moves the arm from home to three positions (A, B, C) and back to home, with a 1-second dwell at each position.</label><textarea style="min-height:130px;" placeholder="; Your G-code program\nG28\nG04 P500\nG01 J1=___ J2=___ F___  ; Move to A\n..."></textarea></div>\n    <div class="ws-field"><label>3. What is the purpose of the M30 command at the end of a G-code file?</label><input type="text" placeholder="M30 signals..."></div>\n    <div class="ws-field"><label>4. Compare Blockly and G-code: when would you choose each, and what is the key limitation of each?</label><textarea placeholder="Blockly: best when... limitation: ...\nG-code: best when... limitation: ..."></textarea></div>\n    <div class="ws-field"><label>5. What is the key advantage of WebSocket over HTTP for this application?</label><textarea placeholder="WebSocket is better here because... HTTP would be a problem because..."></textarea></div>\n    <div class="ws-field"><label>6. Extension: What happens if a G-code command contains a joint angle outside the servo\'s range? How should this be handled, and where in the software stack should the check occur?</label><textarea placeholder="If an out-of-range angle is commanded... The check should occur at... because..."></textarea></div>\n  </div>'
};
